package main

import (
    "encoding/json"
    "fmt"
    "log"

    "github.com/pilot-protocol/common/driver"
    "github.com/pilot-protocol/common/protocol"
    "github.com/pilot-protocol/dataexchange"
)

func main() {
    d, err := driver.Connect("")
    if err != nil {
        log.Fatal(err)
    }

    // Submit task to partner's data agent
    task := map[string]any{
        "description": "Analyze Q1 revenue trends for NASDAQ tech sector",
        "payload": map[string]any{
            "sectors":  []string{"tech"},
            "exchange": "NASDAQ",
            "period":   "Q1-2026",
        },
    }

    body, _ := json.Marshal(task)

    // Dial the partner's data agent on the data-exchange port (1001)
    partner, _ := protocol.ParseAddr("0:0000.0000.0042")
    cl, err := dataexchange.Dial(d, partner)
    if err != nil {
        log.Fatal(err)
    }
    defer cl.Close()

    // Send the task as JSON over the encrypted tunnel;
    // Send returns once the partner's daemon acknowledges it
    res, err := cl.Send(&dataexchange.Frame{Type: dataexchange.TypeJSON, Payload: body})
    if err != nil {
        log.Fatal(err)
    }
    fmt.Printf("Delivered: %s\n", res.Ack.Payload)

    // The partner's agent answers with a message of its own, which lands
    // in this daemon's inbox: pilotctl --json inbox --from 0:0000.0000.0042
    // No shared API, no API keys, no firewall rules
}
